// Parse Claude's JSON response, compute aggregate, decide route.
const input = $input.first().json;
const ctx = $('Load Rubric + Pre-Flight').item.json;

let scored;
try {
  const text = input.content?.[0]?.text || input.completion || '';
  // Strip any leading/trailing prose Claude might have added.
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('no JSON object in response');
  scored = JSON.parse(jsonMatch[0]);
} catch (e) {
  return [{ json: { status: 'halted', reason: 'unparseable_score', error: e.message, raw: input } }];
}

if (scored.halted) {
  return [{ json: { status: 'halted', reason: scored.halted, ctx } }];
}

const dims = ['skill_match', 'level_fit', 'location_fit', 'response_likelihood'];
const clean = {};
let aggregate = 0;
for (const d of dims) {
  const score = Number(scored[d]?.score) || 1;
  const evidence = scored[d]?.evidence || '';
  // Evidence requirement: empty evidence → score 1 regardless of model output.
  const finalScore = (score > 1 && evidence.trim().length > 0) ? Math.min(5, Math.max(1, score)) : 1;
  clean[d] = { score: finalScore, evidence: evidence.slice(0, 200) };
  aggregate += finalScore;
}

let route;
if (aggregate >= 16) route = 'fast-track';
else if (aggregate >= 12) route = 'review-needed';
else route = 'surfaced-not-rejected';

// EU-candidate override: AI-screening notice must be confirmed before fast-track.
if (ctx.is_eu_candidate && route === 'fast-track') {
  route = 'review-needed';
}

return [{
  json: {
    status: 'scored',
    application_id: ctx.application_id,
    candidate_id: ctx.candidate_id,
    candidate_name_first: ctx.candidate_name_first,
    role_slug: ctx.role_slug,
    rubric_sha: ctx.rubric_sha,
    is_eu_candidate: ctx.is_eu_candidate,
    scores: clean,
    aggregate,
    route,
    scored_at: new Date().toISOString(),
  }
}];

