// Append one JSONL audit-log line per scored application.
// No PII (no candidate name, no resume content). Just the route + scores + rubric hash.
const fs = require('fs');
const path = require('path');

const AUDIT_DIR = $env.AUDIT_DIR || '/data/audit';
fs.mkdirSync(AUDIT_DIR, { recursive: true });

const input = $input.first().json;
const yyyymm = new Date().toISOString().slice(0, 7);
const auditPath = path.join(AUDIT_DIR, `${yyyymm}.jsonl`);

const entry = {
  ts: new Date().toISOString(),
  application_id: input.application_id,
  role_slug: input.role_slug,
  rubric_sha: input.rubric_sha,
  scores: {
    skill: input.scores.skill_match.score,
    level: input.scores.level_fit.score,
    location: input.scores.location_fit.score,
    response: input.scores.response_likelihood.score,
  },
  aggregate: input.aggregate,
  route: input.route,
  is_eu_candidate: !!input.is_eu_candidate,
  model: 'claude-sonnet-4-6',
};

fs.appendFileSync(auditPath, JSON.stringify(entry) + '\n', 'utf8');

return [{ json: { audit_appended: auditPath, entry } }];
